def is_balanced(s):
    stack = []
    for char in s:
        if char == '(':
            stack.append(char)
        elif char == ')':
            if not stack:
                return False
            stack.pop()
    return len(stack) == 0

def match_parens(lst):
    if len(lst) != 2:
        return 'No'

    s1, s2 = lst[0], lst[1]

    if any(char not in '()' for char in s1 + s2):
        return 'No'

    if is_balanced(s1 + s2) or is_balanced(s2 + s1):
        return 'Yes'
    else:
        return 'No'

